@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap');
:root{--sc-orange:#f47c20;--sc-green:#169179;--sc-blue:#0057b8;--sc-light:#eaf4ff;--sc-gray:#f5f7f8;--sc-dark:#263238;--sc-white:#fff;--sc-gold:#f6b21a;}
*{box-sizing:border-box}.sc-landing-page{font-family:Poppins,Arial,sans-serif;color:var(--sc-dark);background:#fff;line-height:1.55}.sc-landing-page img{max-width:100%;height:auto}.sc-wrap{width:92%;max-width:1180px;margin:0 auto}.site-header-wrapper{font-family:Poppins,Arial,sans-serif}.site-header-wrapper .section-banner{display:block;background-size:cover;background-position:center;text-align:center}.site-header-wrapper .section-banner img{max-width:100%;height:auto;display:block;margin:0 auto}.rd-navbar{background:#fff;box-shadow:0 8px 25px rgba(0,0,0,.08);position:relative;z-index:99}.rd-navbar-container{width:92%;max-width:1180px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:20px}.rd-navbar-panel{display:flex;align-items:center;gap:15px}.rd-navbar-logo img.logo-small{display:none}.rd-navbar-logo img.logo-default{max-width:210px;height:auto}.rd-navbar-info{margin-left:auto}.rd-navbar-info .info{text-align:right}.info-heading{font-size:12px;font-weight:700;color:var(--sc-orange);text-transform:uppercase}.info-link{font-size:20px;font-weight:800;color:var(--sc-green);text-decoration:none}.info-small{font-size:12px;color:#59666b}.appointment-button{display:inline-block;margin-top:5px;background:var(--sc-orange);color:#fff!important;text-decoration:none;border-radius:8px;padding:8px 14px;font-weight:700;font-size:13px}.sc-main-nav-section{background:var(--sc-green)}.sc-main-nav-section .rd-navbar-container{justify-content:center}.rd-navbar-nav{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;align-items:center;justify-content:center}.rd-nav-link{display:block;padding:13px 14px;color:#fff!important;text-decoration:none;font-weight:700;font-size:14px}.rd-nav-link:hover{background:rgba(255,255,255,.14)}.rd-navbar-toggle,.rd-navbar-info-toggle{display:none}.sc-hero{position:relative;min-height:540px;display:flex;align-items:center;background-size:cover;background-position:center;overflow:hidden}.sc-hero:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(22,145,121,.92),rgba(0,87,184,.78),rgba(244,124,32,.28));}.sc-hero .sc-wrap{position:relative;z-index:2;color:#fff;display:grid;grid-template-columns:1.1fr .9fr;gap:38px;align-items:center}.sc-kicker{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.17);border:1px solid rgba(255,255,255,.25);border-radius:999px;padding:8px 14px;font-weight:800;text-transform:uppercase;font-size:12px;letter-spacing:.08em}.sc-hero h1{font-size:clamp(36px,5vw,64px);line-height:1.03;margin:18px 0 16px;font-weight:800}.sc-hero p{font-size:18px;max-width:720px}.sc-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}.sc-btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;background:var(--sc-orange);color:#fff!important;text-decoration:none;border:0;border-radius:10px;padding:12px 20px;font-weight:800;box-shadow:0 12px 24px rgba(244,124,32,.24);transition:.2s}.sc-btn:hover{transform:translateY(-2px);filter:brightness(.98)}.sc-btn.green{background:var(--sc-green);box-shadow:0 12px 24px rgba(22,145,121,.22)}.sc-btn.blue{background:var(--sc-blue);box-shadow:0 12px 24px rgba(0,87,184,.22)}.sc-card{background:#fff;border-radius:18px;box-shadow:0 20px 48px rgba(0,0,0,.16);padding:28px;color:var(--sc-dark)}.sc-card h3{margin:0 0 10px;color:var(--sc-green);font-size:24px}.sc-form input,.sc-form select,.sc-form textarea{width:100%;border:1px solid #d8e5e7;border-radius:9px;padding:12px 14px;margin:7px 0;font-size:14px}.sc-form textarea{min-height:100px}.sc-section{padding:78px 0}.sc-section.alt{background:var(--sc-gray)}.sc-section.blue{background:var(--sc-light)}.sc-title{text-align:center;max-width:850px;margin:0 auto 38px}.sc-title h2{font-size:clamp(28px,3vw,42px);color:var(--sc-green);margin:0 0 10px;font-weight:800}.sc-title p{font-size:17px;color:#536267}.sc-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.sc-grid.two{grid-template-columns:repeat(2,1fr)}.sc-feature{background:#fff;border-radius:16px;padding:26px;box-shadow:0 12px 30px rgba(0,0,0,.08);border-top:5px solid var(--sc-orange)}.sc-feature h3{margin:0 0 10px;color:var(--sc-green);font-size:21px}.sc-feature p{color:#536267;margin:0}.sc-media-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.sc-photo{border-radius:18px;overflow:hidden;box-shadow:0 18px 42px rgba(0,0,0,.16);min-height:260px;background-size:cover;background-position:center}.sc-video{position:relative;padding-bottom:56.25%;height:0;border-radius:18px;overflow:hidden;box-shadow:0 18px 42px rgba(0,0,0,.16);background:#111}.sc-video iframe{position:absolute;inset:0;width:100%;height:100%;border:0}.sc-comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px}.sc-pro,.sc-con{padding:24px;border-radius:16px;background:#fff;box-shadow:0 12px 30px rgba(0,0,0,.08)}.sc-pro{border-left:6px solid var(--sc-green)}.sc-con{border-left:6px solid #d9534f}.sc-links{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}.sc-links a{background:#fff;border:1px solid #d8e5e7;border-radius:999px;padding:9px 14px;color:var(--sc-green);text-decoration:none;font-weight:700}.sc-comments{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.sc-comment{background:#fff;border-radius:16px;padding:22px;box-shadow:0 12px 28px rgba(0,0,0,.08);font-style:italic}.sc-footer{background:var(--sc-green);color:#fff;text-align:center;padding:22px}.footer-section{background:#0e1719;color:#fff}.footer-section a{color:#fff}.footer-social-icons{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin:16px 0}.footer-links ul{list-style:none;padding:0}.footer-review-blocks{display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin:18px 0}.footer-review-box a{display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.08);border-radius:10px;padding:10px;text-decoration:none}.sc-theme-dark .sc-hero:before{background:linear-gradient(90deg,rgba(38,50,56,.92),rgba(22,145,121,.75),rgba(244,124,32,.35))}.sc-theme-blue .sc-hero:before{background:linear-gradient(90deg,rgba(0,87,184,.92),rgba(22,145,121,.7),rgba(244,124,32,.3))}.sc-theme-orange .sc-hero:before{background:linear-gradient(90deg,rgba(244,124,32,.9),rgba(22,145,121,.72),rgba(0,87,184,.42))}.sc-theme-clean .sc-hero:before{background:rgba(255,255,255,.88)}.sc-theme-clean .sc-hero .sc-wrap{color:var(--sc-dark)}.sc-theme-clean .sc-kicker{background:var(--sc-light);color:var(--sc-green);border-color:#d8e5e7}.sc-mini-hero{min-height:420px}.sc-price-badge{display:inline-block;background:#fff;color:var(--sc-green);font-size:30px;font-weight:800;border-radius:16px;padding:12px 18px;margin:10px 0;box-shadow:0 16px 30px rgba(0,0,0,.16)}
